import heapq
from collections import Counter

def reorganize_string(s):
    counts = Counter(s)
    heap = [(-c, ch) for ch, c in counts.items()]
    heapq.heapify(heap)

    result = []
    prev = None

    while heap or prev:
        if prev and not heap:
            return ""
        count, ch = heapq.heappop(heap)
        result.append(ch)
        count += 1

        if prev:
            heapq.heappush(heap, prev)
            prev = None
        if count < 0:
            prev = (count, ch)

    return "".join(result)

